#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_have_the_shapes_the_constructions_read_them_with() {
        assert_eq!(MD5_WORD.len(), 64);
        assert_eq!(MD4_WORD.len(), 48);
        assert_eq!(K256.len(), 64);
        assert_eq!(K512.len(), 80);
        assert_eq!(WP_TABLE.len(), 256);
        assert_eq!(WP_RC.len(), 10);
    }

    #[test]
    fn the_whirlpool_table_opens_and_closes_on_the_sources_own_rows() {
        // The first row is `LL(0x18, 0x18, 0x60, 0x18, 0xc0, 0x78, 0x30, 0xd8)` and
        // the last `LL(0x86, 0x86, 0x22, 0x86, 0x44, 0xa4, 0x11, 0xc2)`, each read as
        // a little-endian `u64`. Pinning them here is what makes a parse that silently
        // read zero rows or the wrong column visible in a unit test rather than only in
        // the differential court.
        assert_eq!(WP_TABLE[0], 0xd83078c018601818);
        assert_eq!(WP_TABLE[255], 0xc211a44486228686);
        // Every entry is eight bytes, so no bit above bit 63 of any byte position may
        // survive: the high byte of the little-endian read is the row's eighth byte.
        for entry in WP_TABLE {
            assert!(entry >> 56 <= 0xff);
        }
    }
}
